// 00 - Arguments: the semihosting command line really reaches os_main ().
// One suite, one file: it registers itself with the runner; there is no list
// of suites to keep in step with the files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>

#include <cstdio>
#include <cstring>

namespace mtp_args
{
  extern int argc;
  extern char** argv;
} // namespace mtp_args

namespace
{
  bool
  contains (const char* text, const char* what) noexcept
  {
    return text != nullptr && std::strstr (text, what) != nullptr;
  }

  bool
  ends_with (const char* text, const char* suffix) noexcept
  {
    if (text == nullptr || suffix == nullptr)
      {
        return false;
      }
    const std::size_t length = std::strlen (text);
    const std::size_t tail = std::strlen (suffix);
    return length >= tail
           && std::strcmp (text + (length - tail), suffix) == 0;
  }
} // namespace

mt::static_suite suite_args{
  "00 - Arguments", mtp_board::runner (),
  [] (mt::suite& ts) {
    // What the C runtime handed to os_main (), copied by main.cpp.
    const int argc = mtp_args::argc;
    char** argv = mtp_args::argv;

    std::printf ("# argc=%d", argc);
    for (int i = 0; i < argc; ++i)
      {
        std::printf (" argv[%d]=\"%s\"", i,
                     argv != nullptr && argv[i] != nullptr ? argv[i] : "(null)");
      }
    std::printf ("\n");

    ts.test ("os_main () received argc/argv", [=] (auto& t) {
      t.expect (mt::ge (argc, 3))
          << "the program name, --output-file and its path";
      t.expect (argv != nullptr) << "argv is not null";
      t.expect (argc == mtp_board::argument_count ())
          << "mtp_board parsed the same count";
    });

    ts.test ("argv[0] names the test", [=] (auto& t) {
      const char* name = mtp_board::argument (0);
      t.expect (contains (name, "mtp-args"))
          << "argv[0] is the test the runner started";
    });

    ts.test ("the runner passed --output-file and the TAP path", [=] (auto& t) {
      const char* option = mtp_board::argument (1);
      const char* path = mtp_board::argument (2);
      t.expect (option != nullptr && std::strcmp (option, "--output-file") == 0)
          << "argv[1] is --output-file";
      t.expect (ends_with (path, ".tap"))
          << "argv[2] is the report file";
      t.expect (mtp_board::argument (argc) == nullptr)
          << "argv[argc] is a null pointer";
    });
  }
};
